# Core implementation of chunking properties from src/fme/utils/config_utils.py
import math
import tqdm
from functools import partial
from typing import Optional, Tuple, Union, Dict, Any

import torch

round_func = math.ceil

class MemoryEfficientMixin:
    _num_chunk = None
    _spatial_slicing = True
    _num_spatial_chunk = None
    _pbar_kwargs = dict(
        disable=True,
    )

    @property
    def num_chunk(self):
        return self._num_chunk

    @num_chunk.setter
    def num_chunk(self, value):
        assert isinstance(value, int)
        self._num_chunk = value

    @property
    def spatial_slicing(self):
        return self._spatial_slicing

    @spatial_slicing.setter
    def spatial_slicing(self, value):
        assert isinstance(value, bool)
        self._spatial_slicing = value

    @property
    def num_spatial_chunk(self):
        return self._num_spatial_chunk if self._num_spatial_chunk is not None else self._num_chunk

    @num_spatial_chunk.setter
    def num_spatial_chunk(self, value):
        assert isinstance(value, int)
        self._num_spatial_chunk = value

    def enable_progressive_bar(self):
        self._pbar_kwargs['disable'] = False

    def disable_progressive_bar(self):
        self._pbar_kwargs['disable'] = True

    def progress_bar(self, *args, **kwargs):
        kw = self._pbar_kwargs.copy()
        kw.update(kwargs)
        return tqdm.tqdm(range(*args), **kwargs)

# Example of chunking in a forward pass (from src/fme/nn/unet_blocks.py - FMEDownBlockMotion)
# This demonstrates both temporal (num_chunk) and spatial (num_spatial_chunk) slicing.
class FMEDownBlockMotion(MemoryEfficientMixin, DownBlockMotion):
    def forward(
            self,
            hidden_states: torch.Tensor,
            temb: Optional[torch.Tensor] = None,
            num_frames: int = 1,
            *args,
            **kwargs,
    ) -> Union[torch.Tensor, Tuple[torch.Tensor, ...]]:
        output_states = ()

        blocks = zip(self.resnets, self.motion_modules)
        for resnet, motion_module in blocks:

            # Temporal chunking applied to resnet processing
            chunk_size = max(round_func(hidden_states.size(0) / self.num_chunk), 1)
            chunk_hidden_states_cache = []
            for i in range(0, hidden_states.size(0), chunk_size):
                chunk_hidden_states = resnet(hidden_states[i:i + chunk_size], temb[i:i + chunk_size])
                chunk_hidden_states_cache.append(chunk_hidden_states)
            hidden_states = torch.cat(chunk_hidden_states_cache, dim=0)

            if self.spatial_slicing:
                # Spatial chunking applied to motion_module processing
                chunk_size = max(round_func(hidden_states.size(-1) / self.num_spatial_chunk), 1)
                chunk_hidden_states_cache = []
                for i in range(0, hidden_states.size(-1), chunk_size):
                    chunk_hidden_states = motion_module(hidden_states[..., i:i + chunk_size], num_frames=num_frames)
                    if not torch.is_tensor(chunk_hidden_states):
                        chunk_hidden_states = chunk_hidden_states[0]
                    chunk_hidden_states_cache.append(chunk_hidden_states)
                hidden_states = torch.cat(chunk_hidden_states_cache, dim=-1)
            else:
                hidden_states = motion_module(hidden_states, num_frames=num_frames)
                if not torch.is_tensor(hidden_states):
                    hidden_states = hidden_states[0]

            output_states = output_states + (hidden_states,)

        if self.downsamplers is not None:
            for downsampler in self.downsamplers:
                chunk_size = max(round_func(hidden_states.size(0) / self.num_chunk), 1)
                chunk_hidden_states_cache = []
                for i in range(0, hidden_states.size(0), chunk_size):
                    chunk_hidden_states = downsampler(hidden_states[i:i + chunk_size])
                    chunk_hidden_states_cache.append(chunk_hidden_states)
                hidden_states = torch.cat(chunk_hidden_states_cache, dim=0)

            output_states = output_states + (hidden_states,)

        return hidden_states, output_states

